# -*- coding: utf-8 -*-
"""
TIC TAC TOE - NATURE NEON (Android / Pydroid 3)
Framework: Kivy
Install Kivy in Pydroid 3 before running this file.
The mountain background is embedded in this single script.
"""
import base64
import io
import random
import math
import os
import struct
import wave

from kivy.app import App
from kivy.clock import Clock
from kivy.core.image import Image as CoreImage
from kivy.core.audio import SoundLoader
from kivy.graphics import Color, Rectangle
from kivy.metrics import dp, sp
from kivy.uix.screenmanager import ScreenManager, Screen, SlideTransition
from kivy.uix.floatlayout import FloatLayout
from kivy.uix.boxlayout import BoxLayout
from kivy.uix.gridlayout import GridLayout
from kivy.uix.button import Button
from kivy.uix.label import Label
from kivy.uix.image import Image as KivyImage
from kivy.uix.popup import Popup
from kivy.utils import get_color_from_hex

BG_DATA = ""

CPU_IMAGE_DATA = ""
HUMAN_IMAGE_DATA = ""

NAVY = get_color_from_hex("#10172B")
PANEL = (0.035, 0.075, 0.16, 0.76)
WHITE = get_color_from_hex("#F1F3FF")
PURPLE = get_color_from_hex("#D0A0FF")
BLUE = get_color_from_hex("#39A9FF")
PINK = get_color_from_hex("#FF4F9A")
GREEN = get_color_from_hex("#9BE7B1")
YELLOW = get_color_from_hex("#FFE29A")

WIN_LINES = ((0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6))


def winner(board):
    for line in WIN_LINES:
        a, b, c = line
        if board[a] and board[a] == board[b] == board[c]:
            return board[a], line
    if all(board):
        return "draw", None
    return None, None


def minimax(board, depth, maximizing, alpha, beta):
    result, _ = winner(board)
    if result == "O":
        return 10 - depth
    if result == "X":
        return depth - 10
    if result == "draw":
        return 0

    if maximizing:
        best = -999
        for i in range(9):
            if not board[i]:
                board[i] = "O"
                best = max(best, minimax(board, depth + 1, False, alpha, beta))
                board[i] = ""
                alpha = max(alpha, best)
                if beta <= alpha:
                    break
        return best
    best = 999
    for i in range(9):
        if not board[i]:
            board[i] = "X"
            best = min(best, minimax(board, depth + 1, True, alpha, beta))
            board[i] = ""
            beta = min(beta, best)
            if beta <= alpha:
                break
    return best


def ai_move(board, difficulty):
    empty = [i for i, v in enumerate(board) if not v]
    if not empty:
        return None
    if difficulty == "Easy":
        return random.choice(empty)
    if difficulty == "Medium" and random.random() < 0.45:
        return random.choice(empty)

    best_score = -999
    choices = []
    for i in empty:
        board[i] = "O"
        score = minimax(board, 0, False, -999, 999)
        board[i] = ""
        if score > best_score:
            best_score, choices = score, [i]
        elif score == best_score:
            choices.append(i)
    return random.choice(choices)


class ScenicLayout(FloatLayout):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        try:
            data = base64.b64decode(BG_DATA)
            self.texture = CoreImage(io.BytesIO(data), ext="jpg").texture
        except Exception as exc:
            self.texture = None
            print("Background image could not load:", exc)
        with self.canvas.before:
            Color(1, 1, 1, 1)
            self.bg_rect = Rectangle(pos=self.pos, size=self.size, texture=self.texture)
            Color(0.015, 0.025, 0.07, 0.28)
            self.tint_rect = Rectangle(pos=self.pos, size=self.size)
        self.bind(pos=self._update_bg, size=self._update_bg)

    def _update_bg(self, *_):
        self.bg_rect.pos = self.pos
        self.bg_rect.size = self.size
        self.tint_rect.pos = self.pos
        self.tint_rect.size = self.size


def glass_button(text, color=WHITE, font_size="18sp", **kwargs):
    btn = Button(
        text=text, color=color, font_size=font_size,
        background_normal="", background_down="",
        background_color=(0.035, 0.065, 0.15, 0.78),
        bold=True, **kwargs
    )
    with btn.canvas.before:
        Color(0.45, 0.72, 1.0, 0.22)
        btn._border = Rectangle(pos=btn.pos, size=btn.size)
    btn.bind(pos=lambda w, p: setattr(w._border, "pos", p),
             size=lambda w, s: setattr(w._border, "size", s))
    return btn


class NeonTicTacToe(App):
    SAMPLE_RATE = 22050

    def _write_wav(self, path, samples):
        """Write normalized mono 16-bit PCM audio for Kivy's Android audio provider."""
        with wave.open(path, "wb") as wav:
            wav.setnchannels(1)
            wav.setsampwidth(2)
            wav.setframerate(self.SAMPLE_RATE)
            frames = bytearray()
            for sample in samples:
                value = max(-1.0, min(1.0, sample))
                frames.extend(struct.pack("<h", int(value * 32767)))
            wav.writeframes(frames)

    def _tone_samples(self, notes, duration, volume=0.18, fade=True):
        """Create a soft synthesized tone/chime without requiring downloaded assets."""
        count = int(self.SAMPLE_RATE * duration)
        output = []
        for i in range(count):
            t = i / self.SAMPLE_RATE
            env = min(1.0, t / 0.012) if fade else 1.0
            if fade:
                env *= max(0.0, min(1.0, (duration - t) / 0.10))
            value = 0.0
            for freq, weight in notes:
                value += weight * math.sin(2.0 * math.pi * freq * t)
            output.append(volume * env * value)
        return output

    def _sequence_samples(self, sequence, gap=0.025):
        """Create a short melodic chime with a soft attack and natural decay."""
        output = []
        for freq, duration, level in sequence:
            count = int(self.SAMPLE_RATE * duration)
            for i in range(count):
                t = i / self.SAMPLE_RATE
                attack = min(1.0, t / 0.018)
                decay = math.exp(-3.2 * t / max(duration, 0.01))
                release = min(1.0, (duration - t) / 0.055)
                env = max(0.0, attack * decay * release)
                fundamental = math.sin(2.0 * math.pi * freq * t)
                overtone = 0.22 * math.sin(2.0 * math.pi * freq * 2.01 * t)
                output.append(level * env * (fundamental + overtone))
            if gap:
                output.extend([0.0] * int(self.SAMPLE_RATE * gap))
        peak = max((abs(x) for x in output), default=1.0)
        if peak > 0.92:
            scale = 0.92 / peak
            output = [x * scale for x in output]
        return output

    def _create_audio_assets(self):
        """Create tiny local WAV assets so the game works offline on Pydroid 3."""
        audio_dir = os.path.join(self.user_data_dir, "audio")
        os.makedirs(audio_dir, exist_ok=True)
        paths = {}
        effects = {
            # Softer, cleaner UI tick. X and O are intentionally unchanged.
            "tap": ([(1046.5, 0.58), (1568.0, 0.16)], 0.075, 0.075),
            "x": ([(660, 0.75), (990, 0.18)], 0.12, 0.16),
            "o": ([(523.25, 0.75), (784, 0.18)], 0.14, 0.16),
            "draw": ([(523.25, 0.45), (440, 0.35), (392, 0.25)], 0.48, 0.13),
        }
        for name, (notes, duration, volume) in effects.items():
            path = os.path.join(audio_dir, name + ".wav")
            self._write_wav(path, self._tone_samples(notes, duration, volume))
            paths[name] = path

        # A more expressive, ascending victory fanfare instead of one static chord.
        win_path = os.path.join(audio_dir, "win.wav")
        victory = [
            (523.25, 0.16, 0.18),   # C5
            (659.25, 0.16, 0.19),   # E5
            (783.99, 0.18, 0.20),   # G5
            (1046.50, 0.24, 0.21),  # C6
            (783.99, 0.13, 0.16),   # G5
            (1046.50, 0.48, 0.24),  # resolving C6
        ]
        self._write_wav(win_path, self._sequence_samples(victory, gap=0.035))
        paths["win"] = win_path

        # Calm neon-style background: warm sustained chords with a gentle
        # repeating pluck pattern. The 12-second loop stays quiet under gameplay.
        music_path = os.path.join(audio_dir, "ambient_music.wav")
        rate = self.SAMPLE_RATE
        duration = 12.0
        progression = [
            ([(130.81, .22), (164.81, .15), (196.00, .13), (246.94, .08)], [261.63, 329.63, 392.00, 493.88]),
            ([(110.00, .22), (130.81, .15), (164.81, .13), (196.00, .08)], [220.00, 261.63, 329.63, 392.00]),
            ([(87.31, .22), (130.81, .15), (174.61, .13), (220.00, .08)], [261.63, 349.23, 392.00, 523.25]),
            ([(98.00, .22), (146.83, .15), (196.00, .13), (246.94, .08)], [293.66, 392.00, 440.00, 587.33]),
        ]
        music = []
        for i in range(int(rate * duration)):
            t = i / rate
            section = min(3, int(t // 3.0))
            local_t = t - section * 3.0
            # Crossfade each chord to avoid clicks at section boundaries.
            fade_in = min(1.0, local_t / 0.35)
            fade_out = min(1.0, (3.0 - local_t) / 0.35)
            pad_env = max(0.0, min(fade_in, fade_out))
            chord, plucks = progression[section]
            value = 0.0
            for freq, weight in chord:
                value += weight * math.sin(2.0 * math.pi * freq * t)
                value += weight * 0.10 * math.sin(2.0 * math.pi * freq * 2.0 * t)

            # Four soft notes per bar, with a short pluck envelope.
            beat = local_t % 0.75
            note_index = min(3, int(local_t / 0.75))
            pluck_env = math.exp(-5.0 * beat / 0.75) * min(1.0, beat / 0.012)
            pluck_freq = plucks[note_index]
            pluck = (math.sin(2.0 * math.pi * pluck_freq * beat)
                     + 0.18 * math.sin(2.0 * math.pi * pluck_freq * 2.0 * beat))
            music.append(0.085 * pad_env * value + 0.020 * pluck_env * pluck)

        self._write_wav(music_path, music)
        paths["music"] = music_path
        return paths

    def _init_audio(self):
        self.sounds = {}
        self.music = None
        try:
            paths = self._create_audio_assets()
            for name, path in paths.items():
                sound = SoundLoader.load(path)
                if sound is not None:
                    self.sounds[name] = sound
            self.music = self.sounds.get("music")
            if self.music:
                self.music.loop = True
                self.music.volume = 0.38
                self.music.play()
        except Exception as exc:
            # Audio is optional: never prevent the game from launching if a device
            # or Pydroid installation has no compatible audio backend.
            print("Audio initialization skipped:", exc)

    def play_sound(self, name):
        sound = self.sounds.get(name) if hasattr(self, "sounds") else None
        if sound:
            try:
                sound.stop()
                sound.play()
            except Exception as exc:
                print("Sound playback skipped:", exc)

    def on_start(self):
        self._init_audio()

    def on_stop(self):
        if self.music:
            try:
                self.music.stop()
            except Exception:
                pass

    def build(self):
        self.title = "Tic Tac Toe - Nature Neon"
        self.score = {"X": 0, "O": 0, "draw": 0}
        self.board = [""] * 9
        self.current = "X"
        self.vs_cpu = True
        self.difficulty = "Hard"
        self.game_over = False
        self.win_line = None
        self.popup = None

        self.manager = ScreenManager(transition=SlideTransition(duration=0.22))
        self.manager.add_widget(self.make_home())
        self.manager.add_widget(self.make_difficulty())
        self.manager.add_widget(self.make_game())
        return self.manager

    def make_home(self):
        screen = Screen(name="home")
        root = ScenicLayout()
        page = BoxLayout(
            orientation="vertical",
            padding=[dp(14), dp(14), dp(14), dp(14)],
            spacing=dp(8)
        )
        page.add_widget(Label(
            text="[b]TIC TAC TOE[/b]", markup=True, color=PURPLE,
            font_size="31sp", size_hint_y=.12
        ))
        page.add_widget(Label(
            text="CHOOSE YOUR GAME MODE", color=WHITE,
            font_size="14sp", size_hint_y=.07
        ))

        # Stack the two mode cards vertically so they fit portrait phones.
        cards = BoxLayout(
            orientation="vertical", spacing=dp(10), size_hint_y=.64
        )

        def make_mode_card(title, subtitle, image_data, accent, callback):
            card = BoxLayout(
                orientation="vertical", spacing=dp(4),
                padding=[dp(10), dp(7), dp(10), dp(7)],
                size_hint_y=.5
            )
            with card.canvas.before:
                Color(0.025, 0.055, 0.13, 0.76)
                card_bg = Rectangle(pos=card.pos, size=card.size)
                Color(accent[0], accent[1], accent[2], 0.48)
                card_border = Rectangle(pos=card.pos, size=(card.width, dp(2)))
            def update_card(_widget, *_):
                card_bg.pos = card.pos
                card_bg.size = card.size
                card_border.pos = (card.x, card.y + card.height - dp(2))
                card_border.size = (card.width, dp(2))
            card.bind(pos=update_card, size=update_card)

            texture = CoreImage(
                io.BytesIO(base64.b64decode(image_data)), ext="jpg"
            ).texture
            art = KivyImage(
                texture=texture, size_hint=(1, .54),
                allow_stretch=True, keep_ratio=True
            )
            card.add_widget(art)
            card.add_widget(Label(
                text=f"[b]{title}[/b]", markup=True, color=WHITE,
                font_size="18sp", size_hint_y=.18, halign="center",
                valign="middle"
            ))
            card.add_widget(Label(
                text=subtitle, color=accent, bold=True,
                font_size="14sp", size_hint_y=.10
            ))
            action = glass_button(
                "SELECT", color=accent, font_size="15sp",
                size_hint_y=.16
            )
            action.bind(on_release=lambda *_: callback())
            card.add_widget(action)
            return card

        cards.add_widget(make_mode_card(
            "PLAY VS COMPUTER", "SMART AI", CPU_IMAGE_DATA, BLUE,
            self.open_difficulty
        ))
        cards.add_widget(make_mode_card(
            "PLAY VS ANOTHER PLAYER", "LOCAL DUEL", HUMAN_IMAGE_DATA, PINK,
            lambda: self.start_game(False)
        ))
        page.add_widget(cards)
        page.add_widget(Label(
            text="NEON MARKS  •  NATURE BACKGROUND", color=WHITE,
            font_size="11sp", size_hint_y=.05
        ))
        exit_btn = glass_button("EXIT", color=PINK, size_hint_y=.08)
        exit_btn.bind(on_release=lambda *_: self.stop())
        page.add_widget(exit_btn)
        root.add_widget(page)
        screen.add_widget(root)
        return screen

    def make_difficulty(self):
        screen = Screen(name="difficulty")
        root = ScenicLayout()
        page = BoxLayout(orientation="vertical", padding=[dp(24), dp(70), dp(24), dp(80)], spacing=dp(14))
        page.add_widget(Label(text="[b]SELECT DIFFICULTY[/b]", markup=True, color=PURPLE,
                              font_size="30sp", size_hint_y=.20))
        page.add_widget(Label(text="Choose how challenging the AI will be",
                              color=WHITE, font_size="14sp", size_hint_y=.12))
        for name, col in (("Easy", GREEN), ("Medium", YELLOW), ("Hard", PINK)):
            b = glass_button(name, color=col, font_size="23sp", size_hint_y=.14)
            b.bind(on_release=lambda _b, n=name: self.start_game(True, n))
            page.add_widget(b)
        back = glass_button("‹  BACK", size_hint_y=.13)
        back.bind(on_release=lambda *_: self.navigate("home"))
        page.add_widget(back)
        root.add_widget(page)
        screen.add_widget(root)
        return screen

    def make_game(self):
        screen = Screen(name="game")
        root = ScenicLayout()
        page = BoxLayout(orientation="vertical", padding=[dp(10), dp(8), dp(10), dp(10)], spacing=dp(6))
        top = BoxLayout(size_hint_y=.065, spacing=dp(8))
        menu = glass_button("‹ MENU", font_size="15sp", size_hint_x=.34)
        menu.bind(on_release=lambda *_: self.navigate("home"))
        self.mode_label = Label(text="VS HARD", color=PURPLE, font_size="15sp", halign="right")
        top.add_widget(menu)
        top.add_widget(self.mode_label)
        page.add_widget(top)

        page.add_widget(Label(text="[b]X       VS       O[/b]", markup=True, color=PURPLE,
                              font_size="30sp", size_hint_y=.085))
        self.score_label = Label(text="", color=WHITE, font_size="18sp",
                                 size_hint_y=.065, bold=True)
        page.add_widget(self.score_label)
        self.status_label = Label(text="YOUR TURN (X)", color=BLUE, font_size="21sp",
                                  size_hint_y=.065, bold=True)
        page.add_widget(self.status_label)

        board_holder = FloatLayout(size_hint_y=.55)
        self.grid = GridLayout(cols=3, rows=3, spacing=dp(5), padding=dp(5),
                               size_hint=(.94, 1), pos_hint={"center_x": .5, "center_y": .5})
        with self.grid.canvas.before:
            Color(0.02, 0.05, 0.13, 0.50)
            self.grid_bg = Rectangle(pos=self.grid.pos, size=self.grid.size)
        self.grid.bind(pos=lambda w, p: setattr(self.grid_bg, "pos", p),
                       size=lambda w, s: setattr(self.grid_bg, "size", s))
        self.cells = []
        for i in range(9):
            cell = Button(text="", font_size="54sp", bold=True,
                          color=BLUE, disabled_color=BLUE,
                          background_normal="", background_down="",
                          background_color=(0.035, 0.065, 0.15, 0.56))
            cell.bind(on_release=lambda _b, n=i: self.play(n))
            self.cells.append(cell)
            self.grid.add_widget(cell)
        board_holder.add_widget(self.grid)
        page.add_widget(board_holder)

        controls = BoxLayout(size_hint_y=.085, spacing=dp(8))
        new_btn = glass_button("↻  NEW GAME", color=BLUE, font_size="16sp")
        new_btn.bind(on_release=lambda *_: self.new_game())
        reset_btn = glass_button("RESET SCORE", font_size="15sp")
        reset_btn.bind(on_release=lambda *_: self.reset_score())
        controls.add_widget(new_btn)
        controls.add_widget(reset_btn)
        page.add_widget(controls)
        root.add_widget(page)
        screen.add_widget(root)
        return screen

    def navigate(self, name):
        if self.manager.current == name:
            return
        self.play_sound("tap")
        self.manager.transition.direction = "right" if name == "home" else "left"
        self.manager.current = name

    def open_difficulty(self):
        self.navigate("difficulty")

    def start_game(self, vs_cpu, difficulty="Hard"):
        self.vs_cpu = vs_cpu
        self.difficulty = difficulty
        self.new_round()
        self.mode_label.text = ("VS " + difficulty.upper()) if vs_cpu else "2 PLAYERS"
        self.navigate("game")
        self.refresh()

    def new_round(self):
        self.board = [""] * 9
        self.current = "X"
        self.game_over = False
        self.win_line = None
        if self.popup:
            self.popup.dismiss()
            self.popup = None

    def new_game(self):
        self.play_sound("tap")
        self.new_round()
        self.refresh()

    def reset_score(self):
        self.play_sound("tap")
        self.score = {"X": 0, "O": 0, "draw": 0}
        self.refresh()

    def refresh(self):
        if not hasattr(self, "cells"):
            return
        for i, cell in enumerate(self.cells):
            mark = self.board[i]
            cell.text = mark
            # Keep neon mark colors even after a cell has been played.
            mark_color = BLUE if mark == "X" else PINK
            cell.color = mark_color
            cell.disabled_color = mark_color
            cell.opacity = 1
            cell.background_color = ((0.12, 0.55, 0.35, 0.70)
                                     if self.win_line and i in self.win_line
                                     else (0.035, 0.065, 0.15, 0.56))
            # Occupied cells and finished games are already blocked in play().
            # Do not disable the Kivy Button: its default disabled styling fades the text to gray.
            cell.disabled = False
        self.score_label.text = (
            f"X  {self.score['X']}      •      DRAWS  {self.score['draw']}      •      {self.score['O']}  O"
        )
        if self.game_over:
            result, _ = winner(self.board)
            self.status_label.text = "IT'S A DRAW!" if result == "draw" else (
                "YOU WIN!" if result == "X" and self.vs_cpu else
                ("COMPUTER WINS!" if self.vs_cpu else f"PLAYER {result} WINS!")
            )
            self.status_label.color = GREEN if result != "draw" else YELLOW
        else:
            self.status_label.text = ("YOUR TURN (X)" if self.current == "X" else
                                      ("COMPUTER THINKING..." if self.vs_cpu else "PLAYER O'S TURN"))
            self.status_label.color = BLUE if self.current == "X" else PINK

    def play(self, index):
        if self.game_over or self.board[index] or (self.vs_cpu and self.current == "O"):
            return
        self.board[index] = self.current
        self.play_sound("x" if self.current == "X" else "o")
        result, line = winner(self.board)
        if result:
            self.finish(result, line)
            return
        self.current = "O" if self.current == "X" else "X"
        self.refresh()
        if self.vs_cpu and self.current == "O":
            for cell in self.cells:
                cell.disabled = True
            Clock.schedule_once(self.computer_turn, 0.38)

    def computer_turn(self, _dt):
        if self.game_over:
            return
        index = ai_move(self.board, self.difficulty)
        if index is None:
            return
        self.board[index] = "O"
        self.play_sound("o")
        result, line = winner(self.board)
        if result:
            self.finish(result, line)
        else:
            self.current = "X"
            self.refresh()

    def finish(self, result, line):
        self.play_sound("draw" if result == "draw" else "win")
        self.game_over = True
        self.win_line = line
        self.score["draw" if result == "draw" else result] += 1
        self.refresh()
        Clock.schedule_once(lambda _dt: self.show_result(result), 0.35)

    def close_result_and_return_home(self):
        """Close the result dialog and return to the main menu."""
        if self.popup:
            self.popup.dismiss()
            self.popup = None
        self.navigate("home")

    def show_result(self, result):
        title = ("DRAW GAME" if result == "draw" else
                 ("YOU WON!" if result == "X" and self.vs_cpu else
                  ("COMPUTER WON!" if self.vs_cpu else f"PLAYER {result} WON!")))
        content = BoxLayout(orientation="vertical", spacing=dp(12), padding=dp(16))
        content.add_widget(Label(text=title, color=GREEN if result != "draw" else YELLOW,
                                 font_size="24sp", bold=True))
        content.add_widget(Label(text="Play another round?", color=WHITE, font_size="17sp"))
        actions = BoxLayout(size_hint_y=.42, spacing=dp(10))
        yes = glass_button("YES", color=GREEN)
        no = glass_button("NO", color=WHITE)
        actions.add_widget(yes)
        actions.add_widget(no)
        content.add_widget(actions)
        self.popup = Popup(title="GAME OVER", content=content, size_hint=(.86, .34),
                           auto_dismiss=False, separator_color=PURPLE,
                           background_color=(0.035, 0.06, 0.14, .98))
        yes.bind(on_release=lambda *_: (self.play_sound("tap"), self.popup.dismiss(), self.new_game()))
        no.bind(on_release=lambda *_: (self.play_sound("tap"), self.close_result_and_return_home()))
        self.popup.open()


if __name__ == "__main__":
    NeonTicTacToe().run()
